import {projectNavigation} from './oncall-navigation.js';
import {escapeHtml as esc} from './message-format.js';
export function remindersView({root,w,view,api,token,run,show,status}){
 const policy=view.policy[0]||{enabled:false,coordinators:[],revision:0n},names=new Map(w.members.map(m=>[m.id,m.name]));
 root.innerHTML=`<a class="back-link" href="#/oncall/${w.project.id}">← ${esc(w.project.name)}</a><div class="page-heading"><div><span class="eyebrow">PLANNING REMINDERS</span><h2>Planning reminders</h2><p class="lead">Cover requests go to the replacement. Coverage warnings go to your planning contacts.</p></div></div>${projectNavigation(w,'reminders')}${!view.ready?'<p class="oc-issues">Notifications need a Hub connection and the canonical HTTPS Desk address.</p>':''}${view.full?'<p class="oc-issues">Reminder storage is full. New reminders may be missing; review coverage manually.</p>':''}${w.canManage?`<form id="reminderForm" class="card oc-form"><label class="checkline"><input type="checkbox" id="remindersEnabled" ${policy.enabled?'checked':''}> Enable planning reminders through Hub</label><label>Planning contacts · choose up to three</label><div class="oc-people">${w.members.map(m=>`<label class="checkline"><input type="checkbox" name="coordinator" value="${esc(m.id)}" ${policy.coordinators.includes(m.id)?'checked':''}> ${esc(m.name)}</label>`).join('')}</div><p class="kv">Contacts need existing project access. Choosing them does not grant permissions.</p><button class="primary">Save reminders</button></form>`:`<p class="oc-footnote">Planning reminders are ${policy.enabled?'enabled':'paused'}. A Desk administrator can change them.</p>`}<details class="card oc-form"><summary>When Desk sends a reminder</summary><p>A new cover request, then at most one follow-up during the 24 hours before it starts. Consent is still required in Desk.</p><p>One combined warning per UTC day when the next seven days contain a coverage problem or need another published plan. Drafts do not count as coverage.</p><p class="kv">Checks rotate through projects, normally within five minutes. This is planning assistance; incident escalation is configured separately. Hub acceptance does not prove that a device received a message or a person read it.</p></details>${status}<div class="section-heading"><h3>${w.canManage?'Recent attempts':'Your recent attempts'}</h3><button id="refreshReminders">Refresh</button></div><div class="card oc-form">${view.jobs.length?view.jobs.map(j=>`<div class="oc-availability-row"><div><strong>${esc(j.title)}</strong><p>${esc(names.get(j.recipient)||'Former project member')} · ${esc(new Date(Number(j.createdAt/1000000n)).toLocaleString())}</p><p class="kv">${esc(j.detail)}</p></div><span class="badge">${esc(Object.keys(j.status)[0]==='accepted'?'Hub accepted':Object.keys(j.status)[0])} · ${j.attempts}/3</span></div>`).join(''):'<p class="kv">No reminders queued yet.</p>'}</div><p class="oc-footnote">Records expire seven days after the relevant shift starts, or seven days after a daily planning warning expires. Copies kept by Hub or downstream channels follow their own retention.</p>`;
 const form=root.querySelector('#reminderForm');if(form)form.onsubmit=e=>{e.preventDefault();run(e.submitter,()=>api().setOncallReminders(token(),w.project.id,policy.revision,{enabled:root.querySelector('#remindersEnabled').checked,coordinators:[...root.querySelectorAll('[name="coordinator"]:checked')].map(n=>n.value)}),()=>show(String(w.project.id),'reminders'));};
 root.querySelector('#refreshReminders').onclick=()=>show(String(w.project.id),'reminders');
}
